/* ── Account panel (online identity in the menu) ─────────────────────────── */
.account-panel {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
  padding: 8px 10px;
  background: var(--mc-tile-panel, rgba(0, 0, 0, 0.25));
  border: 2px solid rgba(0, 0, 0, 0.4);
}

.account-status {
  flex: 1;
  min-width: 120px;
  font-size: 12px;
  opacity: 0.85;
}

.account-error {
  color: #ff8a80;
  font-size: 12px;
